import{_ as o,C as a,o as c,c as l,j as t,a as r,E as n,a2 as i}from"./chunks/framework.M7K9TQZf.js";const g=JSON.parse('{"title":"랜딩 페이지","description":"존재하지 않는 제품 Halyard의 소개 페이지입니다. 랜딩 페이지는 앱과 정반대의 질문을 던집니다. 600행짜리 표를 견딜 수 있느냐가 아니라, 이 부품들로 누군가 읽고 싶어 하는 페이지 하나가 만들어지느냐입니다.","frontmatter":{"title":"랜딩 페이지","order":2,"aside":false},"headers":[],"relativePath":"ko/examples/landing.md","filePath":"ko/examples/landing.md","lastUpdated":1788615590000}'),s={name:"ko/examples/landing.md"};function p(P,e,h,m,u,x){const d=a("Demo");return c(),l("div",null,[e[0]||(e[0]=t("h1",{id:"랜딩-페이지",tabindex:"-1"},[r("랜딩 페이지 "),t("a",{class:"header-anchor",href:"#랜딩-페이지","aria-label":'Permalink to "랜딩 페이지"'},"​")],-1)),e[1]||(e[1]=t("p",{class:"plass-lede"},"존재하지 않는 제품 Halyard의 소개 페이지입니다. 랜딩 페이지는 앱과 정반대의 질문을 던집니다. 600행짜리 표를 견딜 수 있느냐가 아니라, 이 부품들로 누군가 읽고 싶어 하는 페이지 하나가 만들어지느냐입니다.",-1)),n(d,{src:"examples/landing",flutter:!1,"min-height":1e3}),e[2]||(e[2]=i('<p>페이지 전체가 파일 하나입니다. <code>docs/.vitepress/demos/examples/landing.tsx</code>. 실제로 동작하는 페이지라 요금제를 월 단위로 바꾸고, 후기를 넘겨 보고, FAQ를 열어 볼 수 있습니다.</p><h2 id="구성" tabindex="-1">구성 <a class="header-anchor" href="#구성" aria-label="Permalink to &quot;구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>블록</th><th>컴포넌트</th><th>눈여겨볼 점</th></tr></thead><tbody><tr><td>Nav</td><td><code>PlToolbar</code> <code>PlTextLink</code> <code>PlButton</code></td><td><code>render={&lt;header /&gt;}</code>가 진짜 landmark로 만들고, <code>position=&quot;sticky&quot;</code>가 call to action을 계속 손 닿는 곳에 둡니다</td></tr><tr><td>Hero</td><td><code>PlChip</code> <code>PlTypography</code> <code>PlButton</code> <code>PlAvatar</code> <code>PlRating</code></td><td>겹친 avatar는 <code>PlStack</code>입니다. 음수 margin과 ring이고, avatar에 대한 것은 아무것도 없습니다</td></tr><tr><td>제품 화면</td><td><code>PlTabs</code> <code>PlTab</code> <code>PlTabPanel</code> <code>PlAspectRatio</code></td><td>같은 비율의 panel 셋이라 전환해도 페이지가 움직이지 않습니다</td></tr><tr><td>기능</td><td><code>PlGrid</code> <code>PlGridItem</code> <code>PlCard</code> <code>PlIcon</code></td><td>각 item에 responsive <code>span</code> 하나(12, 6, 3)이 그 줄의 규칙 전부입니다</td></tr><tr><td>후기</td><td><code>PlCarousel</code> <code>PlBlockquote</code></td><td>scroll snap 위에 얹혀 있어서 휴대폰에서 스와이프되고 RTL에서 방향이 뒤집힙니다</td></tr><tr><td>요금제</td><td><code>PlSegmentedButton</code> <code>PlCard</code> <code>PlChip</code> <code>PlIcon</code> <code>PlButton</code></td><td>월/연은 둘 중 하나이고, 추천 요금제는 다른 색이 아니라 <code>elevation={3}</code>입니다</td></tr><tr><td>FAQ</td><td><code>PlAccordion</code> <code>PlAccordionItem</code></td><td>하나는 열린 채로 시작합니다. 전부 접힌 accordion은 제목 목록처럼 보입니다</td></tr><tr><td>가입 영역</td><td><code>PlTextField</code> <code>PlButton</code> <code>PlTextLink</code></td><td>진짜 <code>&lt;form&gt;</code>에 진짜 <code>type=&quot;submit&quot;</code>이라 field 안에서 Enter가 동작합니다</td></tr><tr><td>Footer</td><td><code>PlDivider</code> <code>PlTextLink</code></td><td><code>underline=&quot;hover&quot;</code>. 항상 밑줄이 그어진 링크 줄은 경고처럼 읽힙니다</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>추천 요금제는 <strong>elevation과 chip</strong>으로 표시합니다. 채도 높은 fill이 아닙니다. 카드가 전부 색을 두르고 있으면 더 강조할 것이 남지 않습니다.</li><li>섹션 배경은 <code>--plass-glass-press</code>, 라이브러리가 눌린 표면에 쓰는 그 token입니다. 이 파일을 위해 새로 만든 팔레트가 아니라 페이지 자신의 구조입니다.</li><li>모든 제목은 <code>PlTypography</code>의 <code>level</code>입니다. 이 페이지의 타입 스케일은 섹션마다 고른 Tailwind 크기가 아니라 라이브러리의 것입니다.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>화면이 두 개 더 있습니다: <a href="./dashboard">관리자 대시보드</a>와 <a href="./signup">가입</a>.</li><li>컴포넌트별 prop과 예제는 <a href="./../components/">컴포넌트</a>에 있습니다.</li></ul>',7))])}const b=o(s,[["render",p]]);export{g as __pageData,b as default};
